"""Constrained XY Jacobi relaxation with runtime loops over incoming arms."""
from .backend_runtime import Graph, V, named, remove, repeat, rm
from . import oblique


def arm_masks(g, arms, index):
    x, y, _ = g.separate(named(g, 'initial_xy', 'FLOAT_VECTOR'))
    ox, oy, _ = g.separate(rm.read(g, arms, 'origin', index, 'FLOAT_VECTOR'))
    x, y = x-ox, y-oy
    tx, ty, _ = g.separate(rm.read(g, arms, 'tangent', index, 'FLOAT_VECTOR'))
    nx, ny, _ = g.separate(rm.read(g, arms, 'right', index, 'FLOAT_VECTOR'))
    width = rm.read(g, arms, 'width', index)
    station = rm.read(g, arms, 'inner_station', index)
    s, q = x*tx+y*ty, x*nx+y*ny
    lateral = g.math('LESS_THAN', g.math('ABSOLUTE', q), width*.5+1e-5)
    left=oblique.edge_at(g,arms,index,'left',s)
    right=oblique.edge_at(g,arms,index,'right',s)
    lower=(left[0]-ox)*nx+(left[1]-oy)*ny
    upper=(right[0]-ox)*nx+(right[1]-oy)*ny
    tilted_lateral=g.math('GREATER_THAN',q,lower-1e-5)*g.math('LESS_THAN',q,upper+1e-5)
    from .backend_runtime import choose
    lateral=choose(g,rm.read(g,arms,'oblique',index,'BOOLEAN'),tilted_lateral,lateral)
    street = g.math('GREATER_THAN', s, station-1e-5)*lateral
    mouth = g.math('LESS_THAN', g.math('ABSOLUTE', s-station), 1e-5)*lateral
    return street, mouth, (tx, ty)


def build_projection_group(*, suffix=''):
    g = Graph('Street Blosm / Ordered mouth depth constraints'+suffix)
    g.socket('Geometry', 'NodeSocketGeometry')
    g.socket('Arms', 'NodeSocketGeometry')
    g.socket('Geometry', 'NodeSocketGeometry', 'OUTPUT')
    inp = g.node('NodeGroupInput')
    arms = inp.outputs['Arms']
    start, end = repeat(g, inp.outputs['Geometry'], rm.count(g, arms), 'Every arm constraint')
    _, mouth, (tx, ty) = arm_masks(g, arms, V(g, start.outputs['Iteration']))
    blur = g.node('GeometryNodeBlurAttribute', 'Original mouth neighbors')
    blur.data_type = 'FLOAT'; blur.inputs['Iterations'].default_value = 1
    g.bind(mouth, blur.inputs['Value'])
    lock = g.math('GREATER_THAN', V(g, blur.outputs['Value']), 0.)*(1.-named(g, 'fixed_xy', 'BOOLEAN'))
    x, y, _ = g.separate(named(g, '_shared_candidate', 'FLOAT_VECTOR'))
    ix, iy, _ = g.separate(named(g, 'initial_xy', 'FLOAT_VECTOR'))
    depth = ((x-ix)*tx+(y-iy)*ty)*lock
    step = g.store(start.outputs['Geometry'], '_shared_candidate',
                   g.xyz(x-depth*tx, y-depth*ty, 0.), 'POINT', 'FLOAT_VECTOR')
    g.bind(step, end.inputs['Geometry'])
    out = g.node('NodeGroupOutput'); g.bind(end.outputs['Geometry'], out.inputs['Geometry'])
    return g.g


def build_group(*, suffix=''):
    projection = build_projection_group(suffix=suffix)
    g = Graph('Street Blosm / Constrained quad relaxation'+suffix)
    g.socket('Geometry', 'NodeSocketGeometry'); g.socket('Arms', 'NodeSocketGeometry')
    g.socket('Iterations', 'NodeSocketInt', default=20)
    g.socket('Geometry', 'NodeSocketGeometry', 'OUTPUT')
    inp = g.node('NodeGroupInput'); arms = inp.outputs['Arms']
    g.section('Fix physical boundaries and full incoming profiles')
    geo = g.store(inp.outputs['Geometry'], 'initial_xy', g.position(), 'POINT', 'FLOAT_VECTOR')
    geo = g.store(geo, 'fixed_xy', g.math('MAXIMUM',named(g, 'outer_boundary', 'BOOLEAN'),
                                      named(g,'plateau_boundary','BOOLEAN')), 'POINT', 'BOOLEAN')
    start, end = repeat(g, geo, rm.count(g, arms), 'Every incoming street')
    street, _, _ = arm_masks(g, arms, V(g, start.outputs['Iteration']))
    step = g.store(start.outputs['Geometry'], 'fixed_xy',
                   g.math('MAXIMUM', street, named(g, 'fixed_xy', 'BOOLEAN')), 'POINT', 'BOOLEAN')
    g.bind(step, end.inputs['Geometry'])

    g.section('Synchronous half-step Jacobi with ordered depth projection')
    start, end = repeat(g, end.outputs['Geometry'], inp.outputs['Iterations'], 'XY relaxation')
    position = g.position()
    blur = g.node('GeometryNodeBlurAttribute', 'Self and edge-neighbor mean')
    blur.data_type = 'FLOAT_VECTOR'; blur.inputs['Iterations'].default_value = 1
    g.bind(position, blur.inputs['Value'])
    degree = g.math('MAXIMUM', V(g, g.node('GeometryNodeInputMeshVertexNeighbors').outputs['Vertex Count']), 1.)
    xyz = g.separate(position); mean = g.separate(V(g, blur.outputs['Value']))
    candidate = [p*.5+(((degree+1.)*m-p)/degree)*.5 for p, m in zip(xyz, mean)]
    geo = g.store(start.outputs['Geometry'], '_shared_candidate', g.xyz(*candidate), 'POINT', 'FLOAT_VECTOR')
    n = g.node('GeometryNodeGroup', 'Apply every mouth constraint'); n.node_tree = projection
    g.bind(geo, n.inputs['Geometry']); g.bind(arms, n.inputs['Arms'])
    move = g.node('GeometryNodeSetPosition')
    g.bind(n.outputs['Geometry'], move.inputs['Geometry'])
    g.bind(1.-named(g, 'fixed_xy', 'BOOLEAN'), move.inputs['Selection'])
    g.bind(named(g, '_shared_candidate', 'FLOAT_VECTOR'), move.inputs['Position'])
    g.bind(move.outputs['Geometry'], end.inputs['Geometry'])
    final = remove(g, end.outputs['Geometry'], '_shared_candidate')
    out = g.node('NodeGroupOutput'); g.bind(final, out.inputs['Geometry'])
    return g.g
